//------------------------------------------------------------------------------
// Memory rom: 8255-words x 32-bit
//------------------------------------------------------------------------------
// Port 0 | Read: Sync  | Write: ---- | 
reg [31:0] rom[0:8254];
initial begin
	$readmemh("otpu_ld4_rom.init", rom);
end
reg [31:0] rom_dat0;
always @(posedge sys_clk_1) begin
	rom_dat0 <= rom[otpulitedram4_otpulitedram4_adr];
end
assign otpulitedram4_otpulitedram4_dat_r = rom_dat0;


//------------------------------------------------------------------------------
// Memory sram: 2048-words x 32-bit
//------------------------------------------------------------------------------
// Port 0 | Read: Sync  | Write: Sync | Mode: Write-First | Write-Granularity: 8
reg [31:0] sram[0:2047];
initial begin
	$readmemh("otpu_ld4_sram.init", sram);
end
reg [10:0] sram_adr0;
always @(posedge sys_clk_1) begin : mem_write_block
	integer we_index;
	for(we_index = 0; we_index < 4; we_index=we_index+1)
		if (otpulitedram4_ram_we[we_index])
			sram[otpulitedram4_ram_adr][we_index*8 +: 8] <= otpulitedram4_ram_dat_w[we_index*8 +: 8];
	sram_adr0 <= otpulitedram4_ram_adr;
end
assign otpulitedram4_ram_dat_r = sram[sram_adr0];


//------------------------------------------------------------------------------
// Memory mem: 28-words x 8-bit
//------------------------------------------------------------------------------
// Port 0 | Read: Sync  | Write: ---- | 
reg [7:0] mem[0:27];
initial begin
	$readmemh("otpu_ld4_mem.init", mem);
end
reg [7:0] mem_dat0;
always @(posedge sys_clk_1) begin
	mem_dat0 <= mem[csr_bankarray_adr];
end
assign csr_bankarray_dat_r = mem_dat0;


